export async function getArticle(id) {
  await wait(150);
  return articles.find((a) => String(a.id) === String(id)) ?? null;
}

// Sidebar list: same category first, then the rest
export async function getRelatedList(id, n = 5) {
  await wait(100);
  const cur = articles.find((a) => a.id === Number(id));
  const others = articles.filter((a) => a.id !== Number(id));
  others.sort((a, b) => (b.category === cur?.category) - (a.category === cur?.category));
  return others.slice(0, n);
}

// Next story for the endless feed: most relevant (same category as the first story) that hasn't been shown
export async function getNextRelated(shownIds) {
  await wait(700);
  const first = articles.find((a) => a.id === shownIds[0]);
  const rest = articles.filter((a) => !shownIds.includes(a.id));
  rest.sort((a, b) => (b.category === first?.category) - (a.category === first?.category));
  return rest[0] ?? null;
}